// Package character is the catalog of playable characters the mod manager offers for folders. The data files are
// generated by scripts/update-character-catalog.mjs; an entry's ID is stored in folders and settings, so it never
// changes once published.
package character

import (
	"embed"
	"encoding/json"
	"fmt"
	"io/fs"
	"slices"
	"strings"
	"sync"
)

//go:embed data/*.json
var data embed.FS

// Character is one catalog entry.
type Character struct {
	ID string `json:"id"`
	// Names holds the display name by UI language: en, ko, ja and zh.
	Names   map[string]string `json:"names"`
	Aliases []string          `json:"aliases,omitempty"`
	Genshin *GenshinAvatar    `json:"genshin,omitempty"`
}

// GenshinAvatar is what Genshin's shared textures need of a character.
type GenshinAvatar struct {
	// Body is the body type of the face light map: boy, girl, lady, loli or male.
	Body string `json:"body"`
	// Avatar is the internal name in the game's shadow ramp files, Avatar_<Body>_<Weapon>_<Avatar>_Tex_*, or "".
	Avatar string `json:"avatar,omitempty"`
}

type catalogFile struct {
	Game       string      `json:"game"`
	Characters []Character `json:"characters"`
}

type catalog struct {
	games  []string
	byGame map[string][]Character
}

var load = sync.OnceValue(func() catalog {
	loaded, err := parse(data)
	if err != nil {
		panic(err)
	}
	return loaded
})

func parse(files fs.FS) (catalog, error) {
	names, err := fs.Glob(files, "data/*.json")
	if err != nil {
		return catalog{}, fmt.Errorf("list character catalog: %w", err)
	}
	loaded := catalog{byGame: map[string][]Character{}}
	for _, name := range names {
		raw, err := fs.ReadFile(files, name)
		if err != nil {
			return catalog{}, fmt.Errorf("read character catalog %s: %w", name, err)
		}
		var file catalogFile
		if err := json.Unmarshal(raw, &file); err != nil {
			return catalog{}, fmt.Errorf("parse character catalog %s: %w", name, err)
		}
		loaded.games = append(loaded.games, file.Game)
		loaded.byGame[file.Game] = file.Characters
	}
	slices.Sort(loaded.games)
	return loaded, nil
}

// Games lists the importers, such as GIMI, that have a catalog.
func Games() []string { return slices.Clone(load().games) }

// List returns the characters of a game's importer.
func List(game string) []Character { return slices.Clone(load().byGame[game]) }

// Lookup finds a character by importer and ID.
func Lookup(game, id string) (Character, bool) {
	for _, c := range load().byGame[game] {
		if c.ID == id {
			return c, true
		}
	}
	return Character{}, false
}

// Name is the character's name in a UI language such as "ko" or "zh-CN", falling back to English and then the ID.
func (c Character) Name(lang string) string {
	base, _, _ := strings.Cut(strings.ToLower(lang), "-")
	if name := c.Names[base]; name != "" {
		return name
	}
	if name := c.Names["en"]; name != "" {
		return name
	}
	return c.ID
}
